import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import { projectsAPI } from '../../services/api';
import { usePermissions } from '../../context/PermissionsContext';
import AppLayout from '../../components/layout/AppLayout';
import { T, fmtFCFA, fmtDate, Card, CardHeader, KPI, StatsGrid, ProgressBar, StatusBadge, Badge, DataTable, Btn, Empty, Alert, Modal, Field, Input, Select, Textarea, Spinner, PageContent, PageHeader, PROJECT_STATUS } from '../../components/ui';

const PROJECT_TYPES=[
  {value:'batiment',label:'Bâtiment'},{value:'route',label:'Route / VRD'},
  {value:'aep',label:"Adduction d'eau (AEP)"},{value:'assainissement',label:'Assainissement'},
  {value:'pont',label:'Pont'},{value:'hydraulique',label:'Hydraulique'},
  {value:'electricite',label:'Électricité'},{value:'autre',label:'Autre'},
];
const STATUS_OPTS=[
  {value:'planifie',label:'Planifié'},{value:'en_cours',label:'En cours'},
  {value:'suspendu',label:'Suspendu'},{value:'termine',label:'Terminé'},
];

function NewProjectModal({ open, onClose, onCreated }) {
  const [f,setF]=useState({ name:'',project_type:'batiment',status:'planifie',location:'',description:'',client_name:'',client_email:'',start_date:'',end_date:'',budget:'',reference:'',gps_lat:'',gps_lng:'' });
  const [loading,setLoading]=useState(false);
  const [errors,setErrors]=useState({});
  const s=(k,v)=>setF(p=>({...p,[k]:v}));

  const submit=async()=>{
    setLoading(true);setErrors({});
    try {
      const payload={...f};
      ['budget','gps_lat','gps_lng','start_date','end_date'].forEach(k=>{ if(!payload[k]) delete payload[k]; });
      const res=await projectsAPI.create(payload);
      toast.success('Projet créé !');onCreated(res.data);onClose();
    } catch(err) {
      const d=err?.response?.data;
      if(d&&typeof d==='object') setErrors(d);
      else toast.error('Erreur création.');
    } finally{setLoading(false);}
  };

  return (
    <Modal open={open} onClose={onClose} title="Nouveau projet" width={620}>
      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:14 }}>
        <div style={{ gridColumn:'1/-1' }}><Field label="Nom du projet" required error={errors.name?.[0]}><Input value={f.name} onChange={e=>s('name',e.target.value)} placeholder="Ex: Construction Pont RN7"/></Field></div>
        <Field label="Référence" error={errors.reference?.[0]}><Input value={f.reference} onChange={e=>s('reference',e.target.value)} placeholder="BTP-2025-001"/></Field>
        <Field label="Type de projet" required><Select value={f.project_type} onChange={e=>s('project_type',e.target.value)}>{PROJECT_TYPES.map(t=><option key={t.value} value={t.value}>{t.label}</option>)}</Select></Field>
        <Field label="Statut"><Select value={f.status} onChange={e=>s('status',e.target.value)}>{STATUS_OPTS.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</Select></Field>
        <Field label="Localisation" error={errors.location?.[0]}><Input value={f.location} onChange={e=>s('location',e.target.value)} placeholder="Ex: Bamako, Hamdallaye"/></Field>
        <Field label="Maître d'ouvrage"><Input value={f.client_name} onChange={e=>s('client_name',e.target.value)} placeholder="Ex: Ministère des TP"/></Field>
        <Field label="Email client"><Input type="email" value={f.client_email} onChange={e=>s('client_email',e.target.value)} placeholder="client@ministere.ml"/></Field>
        <Field label="Budget prévu (FCFA)" error={errors.budget?.[0]}><Input type="number" value={f.budget} onChange={e=>s('budget',e.target.value)} placeholder="500000000"/></Field>
        <Field label="Date de début"><Input type="date" value={f.start_date} onChange={e=>s('start_date',e.target.value)}/></Field>
        <Field label="Date de fin prévue"><Input type="date" value={f.end_date} onChange={e=>s('end_date',e.target.value)}/></Field>
        <Field label="Latitude GPS"><Input type="number" value={f.gps_lat} onChange={e=>s('gps_lat',e.target.value)} placeholder="12.6392"/></Field>
        <Field label="Longitude GPS"><Input type="number" value={f.gps_lng} onChange={e=>s('gps_lng',e.target.value)} placeholder="-8.0029"/></Field>
        <div style={{ gridColumn:'1/-1' }}><Field label="Description"><Textarea value={f.description} onChange={e=>s('description',e.target.value)} placeholder="Description du projet, périmètre, objectifs…" rows={3}/></Field></div>
      </div>
      {errors.non_field_errors && <Alert text={errors.non_field_errors} type="danger"/>}
      <div style={{ display:'flex', gap:10, justifyContent:'flex-end', marginTop:20 }}>
        <Btn variant="ghost" onClick={onClose}>Annuler</Btn>
        <Btn onClick={submit} disabled={loading||!f.name}>{loading?'Création…':'Créer le projet'}</Btn>
      </div>
    </Modal>
  );
}

export default function ProjectsPage() {
  const { role, canViewFinancials } = usePermissions();
  const navigate=useNavigate();
  const [projects,setProjects]=useState([]);
  const [loading,setLoading]=useState(true);
  const [showNew,setShowNew]=useState(false);
  const [filter,setFilter]=useState('');
  const [statusFilter,setStatusFilter]=useState('');
  const canCreate=['app_owner','admin_entreprise','office_admin'].includes(role);

  const load=useCallback(async()=>{
    setLoading(true);
    try{
      const params={};
      if(statusFilter) params.status=statusFilter;
      if(filter) params.search=filter;
      const res=await projectsAPI.list(params);
      setProjects(res.data||[]);
    }catch{toast.error('Erreur chargement');}
    finally{setLoading(false);}
  },[filter,statusFilter]);

  useEffect(()=>{load();},[load]);

  const stats={
    total:projects.length, enCours:projects.filter(p=>p.status==='en_cours').length,
    retard:projects.filter(p=>p.is_delayed).length, termine:projects.filter(p=>p.status==='termine').length,
    budgetTotal:projects.reduce((a,p)=>a+(parseFloat(p.budget)||0),0),
  };

  return (
    <AppLayout>
      <PageHeader title="Projets" subtitle={`${stats.total} projet(s)`}
        actions={canCreate&&<div style={{display:'flex',gap:10}}><Btn to="/projects/new" size="sm">+ Nouveau projet</Btn></div>}
      />
      <PageContent>
        <StatsGrid>
          <KPI label="Total" value={stats.total} color={T.orange}/>
          <KPI label="En cours" value={stats.enCours} color={T.amber}/>
          <KPI label="En retard" value={stats.retard} color={T.red} alert={stats.retard>0}/>
          <KPI label="Terminés" value={stats.termine} color={T.green}/>
          {canViewFinancials && <KPI label="Budget total" value={`${(stats.budgetTotal/1e6).toFixed(0)} M FCFA`} color={T.purple}/>}
        </StatsGrid>

        {/* Filters */}
        <div style={{ display:'flex', gap:12, marginBottom:20 }}>
          <input value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Rechercher…"
            style={{ flex:1, background:'#fff', border:`1px solid ${T.border}`, borderRadius:8, padding:'9px 14px', color:T.text, fontSize:13, outline:'none', fontFamily:'inherit' }}/>
          <select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}
            style={{ background:'#fff', border:`1px solid ${T.border}`, borderRadius:8, padding:'9px 14px', color:T.text, fontSize:13, outline:'none', fontFamily:'inherit', cursor:'pointer' }}>
            <option value="">Tous les statuts</option>
            {STATUS_OPTS.map(s=><option key={s.value} value={s.value}>{s.label}</option>)}
          </select>
        </div>

        {loading ? <div style={{ display:'flex', justifyContent:'center', padding:60 }}><Spinner color={T.orange}/></div> :
        !projects.length ? <Empty icon="🏗️" text="Aucun projet." action={canCreate&&<Btn onClick={()=>setShowNew(true)}>+ Créer</Btn>}/> : (
          <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(280px,1fr))', gap:16 }}>
            {projects.map(p=>{
              const pct=p.progress_pct||0;
              const sc=PROJECT_STATUS[p.status]||PROJECT_STATUS.planifie;
              return (
                <div key={p.id} onClick={()=>navigate(`/projects/${p.id}`)}
                  style={{ background:'#fff', border:`1px solid ${T.border}`, borderRadius:12, padding:20, cursor:'pointer', transition:'all .2s', boxShadow:T.shadow }}
                  onMouseOver={e=>{e.currentTarget.style.borderColor=T.orange+'80';e.currentTarget.style.transform='translateY(-2px)';e.currentTarget.style.boxShadow='0 4px 16px rgba(249,115,22,0.12)';}}
                  onMouseOut={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.transform='none';e.currentTarget.style.boxShadow=T.shadow;}}
                >
                  <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:8 }}>
                    <div style={{ fontSize:14, fontWeight:600, color:T.text, flex:1, paddingRight:8 }}>{p.name}</div>
                    <StatusBadge status={p.status}/>
                  </div>
                  {p.reference && <div style={{ fontSize:11, color:T.textMuted, marginBottom:4 }}>Réf: {p.reference}</div>}
                  <div style={{ fontSize:12, color:T.textMuted, marginBottom:10 }}>
                    📍 {p.location||'—'} · {p.project_type_display||p.project_type||''}
                    {p.client_name && <><br/>👤 {p.client_name}</>}
                  </div>
                  <div style={{ display:'flex', justifyContent:'space-between', fontSize:11, color:T.textSub, marginBottom:4 }}>
                    <span>Avancement</span><span style={{ fontWeight:600 }}>{pct}%</span>
                  </div>
                  <ProgressBar pct={pct} color={p.is_delayed?T.red:pct>70?T.green:T.orange}/>
                  {canViewFinancials && <div style={{ fontSize:11, color:T.textMuted, marginTop:8 }}>Budget : {fmtFCFA(p.budget)}</div>}
                  {p.is_delayed && <div style={{ marginTop:6, fontSize:11, color:T.red, fontWeight:600 }}>⚠ Retard détecté</div>}
                  <div style={{ display:'flex', justifyContent:'space-between', marginTop:10, fontSize:11, color:T.textMuted }}>
                    <span>{fmtDate(p.start_date)} → {fmtDate(p.end_date)}</span>
                  </div>
                </div>
              );
            })}
          </div>
        )}
        <NewProjectModal open={showNew} onClose={()=>setShowNew(false)} onCreated={p=>setProjects(prev=>[p,...prev])}/>
      </PageContent>
    </AppLayout>
  );
}
